begin;
-- Keep provider identities unchanged. The two nullable columns are directly editable.
alter table public.players add column name_ko text check(name_ko is null or (char_length(name_ko) between 1 and 80 and name_ko=btrim(name_ko) and name_ko ~ '[가-힣]'));
alter table public.teams add column name_ko text check(name_ko is null or (char_length(name_ko) between 1 and 80 and name_ko=btrim(name_ko) and name_ko ~ '[가-힣]'));
update public.players p set name_ko=n.display_name from public.player_names n where p.id=n.player_id and n.display_name ~ '[가-힣]';

-- Retain aliases and source metadata in the existing table. Direct column edits are
-- manual overrides, protected from later automatic public-name discovery.
create function public.kickx_sync_name_column() returns trigger language plpgsql security definer set search_path='' as $$
begin
 if pg_trigger_depth()>1 then return null;end if;
 if TG_TABLE_NAME='players' then
  if TG_OP='UPDATE' and new.name_ko is not distinct from old.name_ko then return null;end if;
  if new.name_ko is null then delete from public.player_names where player_id=new.id;
  else
   insert into public.player_names(player_id,display_name,aliases,source) values(new.id,new.name_ko,array[new.name],'manual')
   on conflict(player_id) do update set display_name=excluded.display_name,source='manual',source_id=null,updated_at=now();
  end if;
 elsif TG_OP='DELETE' then
  update public.players set name_ko=null where id=old.player_id and name_ko is not null;
 else
  update public.players set name_ko=case when new.display_name ~ '[가-힣]' then new.display_name else null end
  where id=new.player_id and name_ko is distinct from case when new.display_name ~ '[가-힣]' then new.display_name else null end;
 end if;
 return null;
end $$;
create trigger korean_player_column after insert or update of name_ko on public.players for each row execute function public.kickx_sync_name_column();
create trigger korean_player_alias after insert or update or delete on public.player_names for each row execute function public.kickx_sync_name_column();
revoke all on function public.kickx_sync_name_column() from public,anon,authenticated;

-- Preserve the old view column order for watched/owned-player RPC dependencies.
create or replace view public.player_catalog with(security_invoker=true) as
select p.id,p.external_id,p.team_id,p.name,p.english,p.short_name,p.position,p.shirt_number,p.country,p.birth_date,p.trade_status,p.updated_at,p.provider,p.photo,t.league_id,
 case when t.league_id is not null then array[t.league_id] else coalesce(ss.league_ids,'{}'::text[]) end as league_ids,
 concat_ws(' ',p.name,p.english,p.name_ko,t.name,t.english,t.name_ko,l.name,(select string_agg(l2.name,' ') from public.leagues l2 where l2.id=any(ss.league_ids)),n.display_name,array_to_string(n.aliases,' ')) as search_text,
 s.price,s.change_percent,s.performance,s.volume,coalesce(s.goals,ss.goals) as goals,coalesce(s.assists,ss.assists) as assists,coalesce(s.minutes,ss.minutes) as minutes,ss.season,
 s.updated_at as market_updated_at,ss.stats_scope,ss.matches_imported,coalesce(p.name_ko,n.display_name) as display_name,n.aliases,p.name_ko
from public.players p left join public.teams t on t.id=p.team_id left join public.leagues l on l.id=t.league_id left join public.player_market_snapshots s on s.id=p.id left join public.player_season_summaries ss on ss.id=p.id left join public.player_names n on n.player_id=p.id;
create or replace view public.fixture_catalog with(security_invoker=true) as
select f.id,f.external_id,f.league_id,f.home_team_id,f.away_team_id,f.starts_at,f.status,f.home_score,f.away_score,f.updated_at,f.season,
 concat_ws(' ',h.name,h.english,h.name_ko,a.name,a.english,a.name_ko) as search_text,
 case when upper(f.status) in ('1H','HT','2H','ET','BT','P','LIVE') then 'live' when upper(f.status) in ('NS','TBD') then 'scheduled' when upper(f.status) in ('FT','AET','PEN') then 'finished' else 'other' end as state
from public.fixtures f join public.teams h on h.id=f.home_team_id join public.teams a on a.id=f.away_team_id;

-- One atomic, rerunnable import. IDs, provider names and (where verified) birthdays
-- must all agree. Existing manual names survive. No economic fields are changed.
create function public.kickx_apply_korean_catalog(p_players jsonb default '[]',p_teams jsonb default '[]') returns jsonb language plpgsql set search_path='' as $$
declare r jsonb;p public.players%rowtype;t public.teams%rowtype;old_name text;applied_players integer:=0;applied_teams integer:=0;skipped integer:=0;changes jsonb:='[]';begin
 if jsonb_typeof(p_players) is distinct from 'array' or jsonb_typeof(p_teams) is distinct from 'array' or jsonb_array_length(p_players)>10000 or jsonb_array_length(p_teams)>500 then raise exception 'INVALID_INPUT';end if;
 perform pg_catalog.pg_advisory_xact_lock(pg_catalog.hashtextextended('kickx:korean-catalog',0));
 for r in select value from jsonb_array_elements(p_players) loop
  if r->>'name_ko' is null or char_length(r->>'name_ko') not between 1 and 80 or r->>'name_ko' !~ '[가-힣]' then raise exception 'INVALID_INPUT';end if;
  select * into p from public.players where id=r->>'id' for update;
  if not found or p.provider<>'bsd' or p.name is distinct from r->>'name' or (r->>'birth_date' is not null and p.birth_date is distinct from (r->>'birth_date')::date) then skipped:=skipped+1;continue;end if;
  if exists(select 1 from public.player_names where player_id=p.id) then skipped:=skipped+1;continue;end if;
  insert into public.player_names(player_id,display_name,aliases,source,source_id)
  values(p.id,btrim(r->>'name_ko'),array[p.name],case when r->>'source_id' ~ '^Q[0-9]+$' then 'wikidata' else 'transliteration' end,r->>'source_id') on conflict do nothing;
  if found then applied_players:=applied_players+1;changes:=changes||jsonb_build_array(jsonb_build_object('kind','player','id',p.id,'before',p.name_ko,'after',r->>'name_ko'));end if;
 end loop;
 for r in select value from jsonb_array_elements(p_teams) loop
  if r->>'name_ko' is null or char_length(r->>'name_ko') not between 1 and 80 or r->>'name_ko' !~ '[가-힣]' then raise exception 'INVALID_INPUT';end if;
  select * into t from public.teams where id=r->>'id' for update;
  if not found or t.provider<>'bsd' or t.name is distinct from r->>'name' or t.name_ko is not null then skipped:=skipped+1;continue;end if;
  old_name:=t.name_ko;update public.teams set name_ko=btrim(r->>'name_ko') where id=t.id;applied_teams:=applied_teams+1;
  changes:=changes||jsonb_build_array(jsonb_build_object('kind','team','id',t.id,'before',old_name,'after',r->>'name_ko'));
 end loop;
 if applied_players+applied_teams>0 then insert into public.operation_audit(actor,action,detail) values(null,'catalog.korean_names',jsonb_build_object('players',applied_players,'teams',applied_teams,'changes',changes));end if;
 return jsonb_build_object('players',applied_players,'teams',applied_teams,'skipped',skipped);
end $$;
revoke all on function public.kickx_apply_korean_catalog(jsonb,jsonb) from public,anon,authenticated;
grant execute on function public.kickx_apply_korean_catalog(jsonb,jsonb) to service_role;

create or replace function public.kickx_post_json(p public.community_posts) returns jsonb language sql stable security definer set search_path='' as $$
 select jsonb_build_object('id',p.id,'author',coalesce((select nickname from public.profiles where id=p.author_id),'탈퇴한 사용자'),'authorId',p.author_id,'scope',p.scope,'target',p.target,'targetName',case when p.scope='club' then (select coalesce(name_ko,name) from public.teams where id=p.target) else (select coalesce(x.name_ko,n.display_name,x.name) from public.players x left join public.player_names n on n.player_id=x.id where x.id=p.target) end,'category',p.category,'title',p.title,'body',p.body,'date',p.created_at,'updatedAt',p.updated_at,'revision',p.revision,'likes',(select count(*) from public.community_likes where post_id=p.id),'liked',exists(select 1 from public.community_likes where post_id=p.id and user_id=auth.uid()),'views',(select count(*) from public.community_views where post_id=p.id),'commentCount',(select count(*) from public.community_comments where post_id=p.id and status='published'),'transaction',(select jsonb_build_object('id',t.id,'playerId',t.player_id,'playerName',t.player_name,'type',t.side,'quantity',1,'price',t.price,'fee',t.fee,'net',t.net,'date',t.created_at,'status','체결') from public.trades t where t.id=p.trade_id and t.user_id=p.author_id))
$$;

